"""Publish only aggregate metrics, acceptance results and public OSS references."""
import json,pathlib,hashlib,html,shutil,collections
ROOT=pathlib.Path(__file__).resolve().parents[2];P=ROOT/'.research/session-eval'
def main():
 rows=json.loads((P/'validated.json').read_text());out=[]
 for row in rows:
  raw=P/(row['case']+'-'+row['arm']+'.jsonl');events=[json.loads(x) for x in raw.read_text().splitlines() if x.startswith('{')];items={e['item']['id']:e['item'] for e in events if e.get('type')=='item.completed'}
  traces=[]
  for tracefile in (P/(row['case']+'-'+row['arm'])/'.hot-pick-cache/task-catalog/traces').glob('*.json'):
   trace=json.loads(tracefile.read_text());traces.append({'status':trace.get('status'),'catalog_updated_at':trace.get('catalog_updated_at'),'host_reported_outcome':trace.get('host_reported_outcome')})
  commands=[i.get('command','') for i in items.values() if i.get('type')=='command_execution'];ops={op:sum(('hot-pick.mjs '+op) in c for c in commands) for op in ['catalog-route','catalog-detail','read','discover','repo','catalog-record']}
  artifacts={f.name:hashlib.sha256(f.read_bytes()).hexdigest() for f in (P/(row['case']+'-'+row['arm'])).iterdir() if f.name in ['summarize.py','pagination.mjs','index.html','extract.py']}
  artifact_dir=ROOT/'benchmarks/session-eval/artifacts'/row['case']/row['arm'];artifact_dir.mkdir(parents=True,exist_ok=True)
  for name in artifacts:shutil.copyfile(P/(row['case']+'-'+row['arm'])/name,artifact_dir/name)
  for name in ['sales.csv','cards.html','table.html','requirements.txt','README.md']:
   src=P/(row['case']+'-'+row['arm'])/name
   if src.exists():shutil.copyfile(src,artifact_dir/name)
  out.append({k:v for k,v in row.items() if k!='session_id'}|{'completed_item_types':dict(collections.Counter(i.get('type','unknown') for i in items.values())),'hot_pick_command_counts':ops,'catalog_traces':traces,'direct_work_selected':any(t.get('status')=='direct_work' for t in traces),'completed_shell_calls':len(commands),'bounded_source_read_calls':sum('hot-pick.mjs read ' in c and '--find ' in c for c in commands),'source_read_output_bytes':sum(len(i.get('aggregated_output','').encode()) for i in items.values() if 'hot-pick.mjs read ' in i.get('command','')),'hot_pick_tool_output_bytes':sum(len(i.get('aggregated_output','').encode()) for i in items.values() if 'hot-pick.mjs' in i.get('command','')),'artifact_sha256':artifacts,'uncached_input_tokens':row['usage']['input_tokens']-row['usage'].get('cached_input_tokens',0) if row['usage'] else None,'session_log_sha256':hashlib.sha256(raw.read_bytes()).hexdigest()})
 oss_use={
 'money-csv':{'kind':'standard-library documentation guidance','repo':'python/cpython','commit':'acab53212d89b298ba0dd299e8e55c62bf71db80','application':'Host reports applying CSV parsing and exact monetary representation guidance; no added runtime package. Same acceptance behavior achieved by baseline.'},
 'pagination':{'kind':'implementation reference, dependency rejected','repo':'ReApptor/ReApptor.TypeScript.PagedList','commit':'0ba2dbc247bb8271c0016adc6304f998b17feec7','application':'Host reports applying one-based slice and navigation concepts; rejected library runtime because its edge-case semantics differ.'},
 'keyboard-form':{'kind':'skill guidance','repo':'jakubkrehel/skills','commit':'659cc4e5b6df90cfe1f306f5ae1c83fa549e075c','application':'Host reports applying better-accessibility native controls, labels, visible focus and persistent status guidance. Browser grader verifies resulting behavior, not causality.'},
 'html-extraction':{'kind':'runtime library and skill guidance','repo':'D4Vinci/Scrapling','commit':'c5121c7c06a8595ed3a0a9b7b7dcd6802b5ebfc5','runtime_package':'scrapling==0.5.1','application':'Produced extractor imports and calls Scrapling Selector; independently executed in its task-local virtual environment. PyPI wheel is version-pinned, not claimed byte-identical to Git commit.'}}
 for row in out:
  if row['arm']=='hot-pick':row['oss_application']=oss_use[row['case']]
  elif row['arm'].startswith('hot-pick-improved'):row['oss_application']=({'kind':'none','application':'Rejected all inspected skill candidates and implemented directly; no external source claimed applied.'} if row['case']=='pagination' else oss_use[row['case']])
 report={'environment':json.loads((P/'environment.json').read_text()),'method':{'independent_sessions':True,'repetitions_per_arm_per_task':1,'grader':'Predeclared deterministic held-out behavior checks; real Chrome keyboard checks for form. Not an aesthetic or subjective maintainability score.','time':'Wall clock from codex process launch through exit, including startup/discovery/verification. Harness setup and external post-run grading excluded.','tokens':'Raw Codex turn.completed usage. cached_input_tokens is a subset of input_tokens; output_tokens and reasoning_output_tokens reported separately, not double counted or converted to cost.','limitations':['Small constructed realistic fixtures, not production-user experiment','Task set emphasizes focused fixes with no runtime dependencies','Same configured agent/tool environment but independent process/context per arm','Filesystem isolation by directory and instruction, not OS access control','Network and server prompt caching uncontrolled','No statistical generalization from one run per arm']},'revision_disposition':{'first_revision':'Retained: explicit direct-work gate, bounded source reads and description parsing. Gate was not selected in these sessions; pagination improved against original treatment but remained slower than baseline.', 'second_revision':'Experimental verification-batching guidance was rolled back after no overall measured benefit. Its source hashes and all results remain preserved; this arm does not describe the final shipping policy.'},'runs':out,'post_hoc_geometry':json.loads((P/'geometry.json').read_text()) if (P/'geometry.json').exists() else None}
 (ROOT/'docs/session-evaluation.json').write_text(json.dumps(report,indent=2).replace(str(ROOT),'<repository>').replace(str(pathlib.Path.home()),'<home>')+'\n')
 totals={arm:{'seconds':sum(r['wall_seconds'] for r in out if r['arm']==arm),'input':sum(r['usage']['input_tokens'] for r in out if r['arm']==arm),'output':sum(r['usage']['output_tokens'] for r in out if r['arm']==arm),'passed':sum(r['passed'] for r in out if r['arm']==arm),'total':sum(r['total'] for r in out if r['arm']==arm)} for arm in ['baseline','hot-pick']}
 original_finding=f"<h2>Original paired result</h2><p>Both arms passed {totals['baseline']['passed']}/{totals['baseline']['total']} predeclared checks across four tasks. Baseline sessions totalled {totals['baseline']['seconds']:.2f} seconds, {totals['baseline']['input']:,} input tokens and {totals['baseline']['output']:,} output tokens. Original Hot Pick totalled {totals['hot-pick']['seconds']:.2f} seconds, {totals['hot-pick']['input']:,} input tokens and {totals['hot-pick']['output']:,} output tokens. No acceptance-quality gain was measured; discovery and inspection added substantial overhead in this sample.</p><p>Development retests retain the first revision’s mixed results: CSV had lower total input but took longer and produced more output; pagination improved versus original Hot Pick but remained slower than baseline; UI’s first retest increased input substantially. The second UI revision is an adaptive development retest of generic verification-batching guidance, not an independent replication or a replacement for that regression. No zero-network direct-work choice was observed in the first three retests.</p><p>The second UI revision reduced input versus the first UI retest, but increased wall time and output; it remained worse than original Hot Pick on all three totals. Its independent browser checks still passed. The experimental second-revision batching guidance was subsequently rolled back; its hashes and negative results remain preserved. The first revision is retained, with UI overhead unresolved. A separate post-hoc geometry audit at800/320px found zero input/button bounding-box deltas in every UI arm against the original seed. This exploratory audit did not alter the predeclared8/8 scores and found no layout-preservation advantage.</p>"
 table=''.join('<tr>'+''.join('<td>'+html.escape(str(v))+'</td>' for v in [r['case'],r['arm'],str(r['passed'])+'/'+str(r['total']),round(r['wall_seconds'],2),round(r.get('external_grader_seconds',0),2),r['usage']['input_tokens'] if r['usage'] else 'unknown',r['usage'].get('cached_input_tokens',0) if r['usage'] else 'unknown',r['usage']['output_tokens'] if r['usage'] else 'unknown'])+'</tr>' for r in out)
  # Publication contains no raw session text or user-specific paths.
 document='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Independent task-session evaluation</title><style>body{font:16px/1.6 system-ui;max-width:76rem;margin:3rem auto;padding:1rem}table{border-collapse:collapse;font-size:14px}td,th{border:1px solid #ccc;padding:.5rem}pre{white-space:pre-wrap}</style><main><h1>Independent task-session evaluation</h1><p>Actual evaluation date: 2026-11-11. Git display dates do not determine these measurement timestamps.</p><p>Fresh Codex CLI processes, identical task seeds and prompts except Hot Pick instructions, the existing configured gpt-6.1-sol/high model, and held-out deterministic checks. Raw usage comes from turn.completed events, not text-length estimates. Agents completed actual code edits; artifacts and the harness are included.</p>'''+original_finding+'''<table><tr><th>Task</th><th>Arm</th><th>Checks</th><th>Session seconds</th><th>External grader seconds</th><th>Input tokens</th><th>Cached input subset</th><th>Output tokens</th></tr>'''+table+'''</table><h2>Interpretation</h2><p>One run per arm/task is descriptive evidence, not statistically reliable proof of universal superiority. The first three tasks are dependency-free focused changes, deliberately testing unnecessary overhead; the fourth permits free dependencies for heterogeneous HTML extraction. This task mix must not be generalized to complex or unfamiliar integrations.</p><p>Input includes cached tokens; do not add the cached column again. Reasoning token fields are retained separately in JSON and not added a second time to output. These are API-reported session usage counts, not a dollar invoice. Session wall time includes startup, discovery, coding and the agent’s own checks. External acceptance-grader time is separately measured; setup of this evaluation harness is excluded.</p><p>Fresh process and directory do not provide OS-level isolation: sibling reads were prohibited by prompt and no such reads were observed. Global tool and skill metadata can appear in both session contexts; baseline was instructed not to invoke skills. Network and provider caching are uncontrolled. Improved treatment runs are new sessions using unchanged task prompts and updated Hot Pick, not repeated baseline measurements.</p><p>Quality is acceptance behavior coverage, not aesthetic quality, maintainability, security certification or user preference. Original failures and negative outcomes are retained. No claim of causal effect beyond this small sample is made.</p><p><a href="session-evaluation.json">Machine-readable metrics and provenance</a> · <a href="../benchmarks/session-eval/">Harness and produced artifacts</a> · <a href="https://learn.chatgpt.com/docs/non-interactive-mode">Official Codex JSON usage documentation</a> · <a href="https://developers.openai.com/blog/eval-skills">Official skill evaluation guidance</a></p></main></html>'''
 (ROOT/'docs/session-evaluation.html').write_text(document)
 print(json.dumps([{k:r[k] for k in ['case','arm','wall_seconds','usage','passed','total']} for r in out],indent=2))
if __name__=='__main__':main()
